  old.before(master);
  const home = document.createElement('a'); home.href = new URL('index.html', root).href;
  const logo = document.createElement('img'); logo.src = new URL('logo.png', root).href; logo.alt = 'Atlantis Tours and Experiences'; logo.width = 76; logo.style.height = 'auto'; home.append(logo); master.append(home);
  const language = document.createElement('select'); language.className = 'at-language'; language.setAttribute('aria-label','Language / Sprache');
  Object.entries({en:'English',de:'Deutsch',ru:'Русский',fr:'Français',it:'Italiano',es:'Español',pl:'Polski',ar:'العربية',cs:'Čeština',tr:'Türkçe'}).forEach(([k,v])=>language.add(new Option(v,k)));
  language.value=lang; language.addEventListener('change',()=>{try{localStorage.setItem('atlantis_lang',language.value);localStorage.setItem('atlantis:lang',JSON.stringify(language.value))}catch{} location.reload()}); master.append(language);


  document.body.classList.add("at-enhanced");

